}

.success-message {
    color: #28a745;
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-5px); }
    to { opacity: 1; transform: translateY(0); }
}

