+/* Expandable panel */
+.expandable-panel {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    margin-bottom: 1.5rem;
+    overflow: hidden;
+}
+
+.panel-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    width: 100%;
+    padding: 0.75rem 1rem;
+    background: #f8f9fa;
+    border: none;
+    cursor: pointer;
+    font-size: 0.95rem;
+    font-weight: 500;
+}
+
+.panel-header:hover {
+    background: #e9ecef;
+}
+
+.panel-body {
+    padding: 1rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+/* Security */
+.security-item {
+    margin-bottom: 1.5rem;
+    padding: 1rem;
+    background: #f8f9fa;
+    border-radius: 6px;
+}
+
+.status-indicator {
+    margin-left: auto;
+    padding: 0.2rem 0.6rem;
+    border-radius: 12px;
+    font-size: 0.8rem;
+    font-weight: 500;
+}
+
+.status-indicator.enabled {
+    background: #d4edda;
+    color: #155724;
+}
+
+.status-indicator.disabled {
+    background: #f8d7da;
+    color: #721c24;
+}
+
+.muted-text {
+    font-size: 0.85rem;
+    color: #666;
+    margin-top: 0.5rem;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    color: #0d6efd;
+    font-weight: 500;
+}
+
+/* Sessions table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-bottom: 1.5rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 500;
+    font-size: 0.85rem;
+    color: #555;
+}
+
+/* Confirmation dialog */
+.dialog-overlay {
+    position: fixed;
+    top: 0;
+    left: 0;
+    right: 0;
+    bottom: 0;
+    background: rgba(0, 0, 0, 0.4);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.dialog {
+    background: white;
+    padding: 1.5rem;
+    border-radius: 8px;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
+}
+
+.dialog h4 {
+    margin-top: 0;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.25rem;
+}
+
+/* Radio groups */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+    margin-top: 0.25rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Appearance preview */
+.preview-area {
+    margin: 1.5rem 0;
+    padding: 1.5rem;
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    transition: all 0.2s ease;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+}
+
+.preview-card {
+    margin-top: 1rem;
+    padding: 1rem;
+    border: 1px solid #ddd;
+    border-radius: 6px;
+}
+
+.preview-theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+.preview-theme-dark {
+    background: #1e1e2e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-theme-dark .preview-card {
+    border-color: #555;
+    background: #2a2a3e;
+}
+
+.preview-theme-system {
+    background: #f5f5f5;
+    color: #333;
+}
+
+.preview-font-small {
+    font-size: 0.85rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.15rem;
+}
+
+.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.3;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.5rem;
+}
+
+/* Toast */
+.toast {
+    margin-top: 1rem;
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    font-size: 0.9rem;
+    animation: fadeIn 0.3s ease;
+}
+
+.toast.success {
+    background: #d4edda;
+    color: #155724;
+    border: 1px solid #c3e6cb;
+}
+
+/* Messages */
+.error-message {
+    color: #dc3545;
+    font-size: 0.9rem;
+    margin-bottom: 0.75rem;
+}
+
+.success-message {
+    color: #28a745;
+    font-size: 0.9rem;
+    margin-bottom: 0.75rem;
+}
+
+@keyframes fadeIn {
+    from { opacity: 0; transform: translateY(-5px); }
+    to { opacity: 1; transform: translateY(0); }
+}
